import "server-only";
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { SAMPLE_PROJECTS, type ModelSummary, type SampleProject } from "@ifcwise/shared";
import { cacheLife } from "next/cache";

// Reference projects are generated by `npm run samples` into public/samples/<slug>/ and never change at runtime.
export const sampleFile = (slug: string, name: string) => `/samples/${slug}/${name}`;

export function getSample(slug: string): SampleProject | undefined {
  return SAMPLE_PROJECTS.find((s) => s.slug === slug);
}

async function readPublic(slug: string, name: string): Promise<string> {
  "use cache";
  cacheLife("max");
  return readFile(join(process.cwd(), "public", "samples", slug, name), "utf8");
}

export async function getSampleDetails(slug: string): Promise<{ summary: ModelSummary; assumptions: string }> {
  const [summary, assumptions] = await Promise.all([readPublic(slug, "summary.json"), readPublic(slug, "assumptions.md")]);
  return { summary: JSON.parse(summary) as ModelSummary, assumptions };
}
